//! The language a run speaks, chosen the way git chooses it.
//!
//! git speaks the language gettext resolves: `LC_ALL`, else `LC_MESSAGES`, else `LANG` names the
//! locale, a value of `C` or `POSIX` means no translation at all, and `LANGUAGE` is a list of
//! preferences that is read only when the locale is a language. The choice is made once, before
//! any command runs, so every `t!` after it resolves in the selected locale.
//!
//! The choice is among the locales `i18n!` compiled in, which is what
//! [`crate::_rust_i18n_available_locales`] answers. That function is generated by the macro at the
//! crate root and reads the same backend `rust_i18n::set_locale` writes to, so asking it is asking
//! what a language can actually be translated in rather than listing names beside it.

use std::env;

/// The locale used when the environment names none this program can speak.
const FALLBACK_LANGUAGE: &str = "en";

/// Selects the language and binds it to `rust-i18n`.
pub fn select() {
    rust_i18n::set_locale(&chosen_with(environment));
}

/// The locale to run in, decided from `lookup` as the environment would answer it.
///
/// `lookup` is the environment rather than a read of it, so the whole decision is a pure one and
/// the table it follows can be checked without changing the process the tests run in.
pub fn chosen_with(lookup: impl Fn(&str) -> Option<String>) -> String {
    // The category that decides, in gettext's order. An empty variable is not a value: glibc
    // treats it as unset, so a container that exports `LC_ALL=` gets `LANG`.
    let category = ["LC_ALL", "LC_MESSAGES", "LANG"]
        .iter()
        .find_map(|name| valued(lookup(name)));

    // `C` and `POSIX` mean the untranslated program. `LANGUAGE` is not read at all then, which is
    // the difference between `LC_ALL=C LANGUAGE=zh_CN` and `LANGUAGE=zh_CN`.
    if category.as_deref().is_some_and(is_plain) {
        return FALLBACK_LANGUAGE.to_owned();
    }

    // `LANGUAGE` is a colon separated list of what the reader would rather have; the category is
    // what they will take. A language named by neither cannot be spoken.
    let mut wanted: Vec<String> = Vec::new();

    if let Some(list) = valued(lookup("LANGUAGE")) {
        wanted.extend(
            list.split(':')
                .filter(|one| !one.is_empty())
                .map(str::to_owned),
        );
    }

    if let Some(category) = category {
        wanted.push(category);
    }

    let compiled = crate::_rust_i18n_available_locales();

    wanted
        .iter()
        .map(|one| locale_of(one))
        .find(|one| compiled.iter().any(|locale| locale == one))
        .unwrap_or_else(|| FALLBACK_LANGUAGE.to_owned())
}

/// Whether a locale is one gettext does not translate in.
fn is_plain(value: &str) -> bool {
    matches!(locale_of(value).as_str(), "C" | "POSIX")
}

/// An environment value as a locale `rust-i18n` knows.
///
/// `LANG` and friends carry an encoding suffix and a modifier, `zh_CN.UTF-8@x`, and spell the
/// territory with an underscore; none of those belongs in a locale name, so `zh_CN.UTF-8@x`
/// becomes `zh-CN`.
fn locale_of(value: &str) -> String {
    let without_modifier = value.split('@').next().unwrap_or(value);

    without_modifier
        .split('.')
        .next()
        .unwrap_or(without_modifier)
        .replace('_', "-")
}

/// The environment variable `name`, when it has a value.
fn environment(name: &str) -> Option<String> {
    env::var(name).ok()
}

/// `value`, when it is a value at all.
///
/// An empty variable is not one: glibc reads `LC_ALL=` as unset and takes the next in the chain, so
/// a container that exports an empty variable gets the language it would have had without it.
fn valued(value: Option<String>) -> Option<String> {
    value.filter(|value| !value.is_empty())
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use super::chosen_with;

    /// The locale chosen from `pairs`.
    fn chosen(pairs: &[(&str, &str)]) -> String {
        let environment: HashMap<String, String> = pairs
            .iter()
            .map(|(name, value)| ((*name).to_owned(), (*value).to_owned()))
            .collect();

        chosen_with(|name| environment.get(name).cloned())
    }

    #[test]
    fn the_locales_the_program_compiled_are_the_ones_it_chooses_among() {
        let compiled = crate::_rust_i18n_available_locales();

        assert!(compiled.iter().any(|locale| locale == "en"));
        assert!(compiled.iter().any(|locale| locale == "zh-CN"));
    }

    #[test]
    fn nothing_named_is_the_fallback() {
        assert_eq!(chosen(&[]), "en");
    }

    #[test]
    fn lang_names_the_language_when_no_higher_category_does() {
        assert_eq!(chosen(&[("LANG", "zh_CN.UTF-8")]), "zh-CN");
    }

    #[test]
    fn lc_all_is_read_before_lang() {
        assert_eq!(
            chosen(&[("LC_ALL", "zh_CN.UTF-8"), ("LANG", "en_US.UTF-8")]),
            "zh-CN"
        );
    }

    #[test]
    fn lc_messages_is_read_before_lang() {
        assert_eq!(
            chosen(&[("LC_MESSAGES", "zh_CN"), ("LANG", "en_US.UTF-8")]),
            "zh-CN"
        );
    }

    #[test]
    fn a_category_above_language_is_what_is_taken() {
        assert_eq!(
            chosen(&[("LC_MESSAGES", "en"), ("LANG", "zh_CN")]),
            "en",
            "LC_MESSAGES decides, and LANG is never read"
        );
    }

    #[test]
    fn language_is_a_list_of_preferences() {
        assert_eq!(chosen(&[("LANGUAGE", "zh_CN:en")]), "zh-CN");
        assert_eq!(
            chosen(&[("LANGUAGE", "fr:zh_CN")]),
            "zh-CN",
            "a language with no translation is passed over"
        );
    }

    #[test]
    fn language_is_not_read_in_the_c_locale() {
        assert_eq!(chosen(&[("LC_ALL", "C"), ("LANGUAGE", "zh_CN")]), "en");
        assert_eq!(chosen(&[("LANG", "C.UTF-8")]), "en");
    }

    #[test]
    fn a_language_with_no_translation_is_the_fallback() {
        assert_eq!(chosen(&[("LANG", "zh_TW")]), "en");
    }

    #[test]
    fn the_encoding_and_modifier_are_not_part_of_the_name() {
        assert_eq!(chosen(&[("LANG", "zh_CN@x")]), "zh-CN");
        assert_eq!(chosen(&[("LANG", "zh_CN.GB18030")]), "zh-CN");
    }

    #[test]
    fn an_empty_variable_is_one_that_is_not_there() {
        assert_eq!(chosen(&[("LC_ALL", ""), ("LANG", "zh_CN")]), "zh-CN");
    }
}
